#include<stdio.h>

int main(){
	int n;
	scanf("%d",&n);
	int s[10];
	for(int i=0;i<n;i++)scanf("%d",s+i);

	int a[10];
	for(int i=0;i<n;i++){
		//a[i]を求める
		int temp=s[i];
		for(int j=0;j<i;j++)temp-=a[j];
		a[i]=temp;
	}

	for(int i=0;i<n;i++)printf("%d%c",a[i],i==n-1?'\n':' ');
}

#include<stdio.h>

int main(){
	int n;
	scanf("%d",&n);
	int s[11];
	s[0]=0;
	for(int i=1;i<=n;i++)scanf("%d",s+i);

	int a[10];
	for(int i=0;i<n;i++)a[i]=s[i+1]-s[i];

	for(int i=0;i<n;i++)printf("%d%c",a[i],i==n-1?'\n':' ');
}

#include <iostream>
#include <vector>
#include <numeric>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;
    vector<int> S(N);
    for(auto&& s : S)cin >> s;

    vector<int> A(N);
    adjacent_difference(begin(S), end(S), begin(A));

    for(const auto a : A)cout << a << " ";
    cout << endl;

    return 0;
}

